style.css:
@-moz-document domain("gerarpix.com.br") {
main, body {
    background-color: #17171a;
    color: #dedede;
}

.bg-white, .bg-gray-50 {
    background-color: #1c1c22;
}

h1.text-white {
    color: #394a63;
}

.text-gray-500, .text-gray-700, .text-white {
    color: #dedede;
}

.plaquinha-ad {
    display: none;
}

input {
    background-color: #1c1c22;
    color: #dedede;
}

.border-gray-300 {
    border-color: #4d4d4d;
}

.border-transparent {
    border: 1px solid #4d4d4d;
    border-right: 0;
}

.bg-transparent {
    background-color: #1c1c22;
}
}
